//! `storm-replay` — Heroes of the Storm replay decoder (`.StormReplay`).
//!
//! A replay is an MPQ archive: a *header* (user data section) + 6 embedded files.
//! The per-build protocols are embedded in the crate (generated by `tools/protocol_gen.py`
//! from [Blizzard/heroprotocol](https://github.com/Blizzard/heroprotocol)); an unknown build
//! is decoded with the last known protocol (see [`Replay::protocol_fallback`]).
//!
//! ```no_run
//! # fn main() -> storm_replay::Result<()> {
//! let replay = storm_replay::Replay::open("match.StormReplay")?;
//! println!("build {} — {} game loops", replay.header.base_build, replay.header.elapsed_game_loops);
//! let details = replay.details()?;
//! for p in &details.players {
//!     println!("{} ({}) — team {}", p.name, p.hero, p.team_id);
//! }
//! let events = replay.tracker_events()?; // lazy decoding, per stream
//! # Ok(()) }
//! ```

mod attributes;
mod bitpacked;
mod error;
mod protocol;
mod stream;
mod typeinfo;
mod value;
mod versioned;

pub use attributes::{AttributeValue, Attributes};
pub use error::{Error, Result};
pub use protocol::{StreamKind, LATEST_BUILD};
pub use stream::StreamDecoder;
pub use value::Value;

use protocol::Protocol;
use std::path::Path;
use std::sync::Arc;

/// Replay header (decoded on open, with the last known protocol — reference
/// behaviour: the header decodes with any protocol).
#[derive(Debug, Clone)]
pub struct ReplayHeader {
    /// Protocol build (`m_version.m_baseBuild`) — determines the decoding table.
    pub base_build: u32,
    /// Displayed version `major.minor.revision.build`.
    pub version: (i64, i64, i64, i64),
    /// Duration in game loops (16 per second).
    pub elapsed_game_loops: u64,
}

/// Typed view of `replay.details`.
#[derive(Debug, Clone)]
pub struct ReplayDetails {
    /// Localised map name (`m_title`).
    pub title: String,
    /// Windows FILETIME timestamp (`m_timeUTC`, units of 100 ns since 1601-01-01 UTC).
    pub time_utc: i64,
    /// Local offset (`m_timeLocalOffset`, same units).
    pub time_local_offset: i64,
    pub players: Vec<PlayerDetails>,
}

/// A player of `replay.details` (`m_playerList`).
#[derive(Debug, Clone)]
pub struct PlayerDetails {
    pub name: String,
    /// Localised hero name.
    pub hero: String,
    /// 0 = left/blue team, 1 = right/red.
    pub team_id: i64,
    /// 1 = victory, 2 = defeat.
    pub result: i64,
    /// Slot in the working set (links details ↔ tracker/lobby), missing for observers.
    pub working_set_slot_id: Option<i64>,
    /// Identifiant Battle.net stable « region-Hero-realm-id ».
    pub toon_handle: String,
}

/// An open `.StormReplay`: header decoded, **lazy** streams (each accessor decodes
/// its stream when called — nothing is cached, the caller stays in control).
pub struct Replay {
    bytes: Vec<u8>,
    mpq: nom_mpq::MPQ,
    /// Header brut complet (dont `m_ngdpRootKey`, `m_dataBuildNum`…).
    pub header_raw: Value,
    pub header: ReplayHeader,
    protocol: Arc<Protocol>,
    fallback: Option<(u32, u32)>,
}

impl Replay {
    pub fn open(path: impl AsRef<Path>) -> Result<Replay> {
        Replay::from_bytes(std::fs::read(path)?)
    }

    pub fn from_bytes(bytes: Vec<u8>) -> Result<Replay> {
        let (_, mpq) = nom_mpq::parser::parse(&bytes).map_err(|e| Error::Mpq(format!("{e:?}")))?;
        let user_data = mpq
            .user_data
            .as_ref()
            .ok_or_else(|| Error::Mpq("no user data section (header)".into()))?;
        let header_raw = protocol::latest_protocol()?.decode_header(&user_data.content)?;

        let version = header_raw
            .field("m_version")
            .ok_or_else(|| Error::Corrupted("header without m_version".into()))?;
        let vfield = |name: &str| -> Result<i64> {
            version
                .field(name)
                .and_then(Value::as_int)
                .ok_or_else(|| Error::Corrupted(format!("header without m_version.{name}")))
        };
        let base_build = u32::try_from(vfield("m_baseBuild")?)
            .map_err(|_| Error::Corrupted("negative m_baseBuild".into()))?;
        let header = ReplayHeader {
            base_build,
            version: (
                vfield("m_major")?,
                vfield("m_minor")?,
                vfield("m_revision")?,
                vfield("m_build")?,
            ),
            elapsed_game_loops: header_raw
                .field("m_elapsedGameLoops")
                .and_then(Value::as_int)
                .and_then(|v| u64::try_from(v).ok())
                .unwrap_or(0),
        };

        let (protocol, used_fallback) = protocol::protocol_for_build(base_build)?;
        let fallback = used_fallback.then_some((base_build, LATEST_BUILD));
        Ok(Replay {
            bytes,
            mpq,
            header_raw,
            header,
            protocol,
            fallback,
        })
    }

    /// `Some((requested build, used build))` if the replay's build has no exact table
    /// (replay newer than the embedded protocols) — to be logged by the caller.
    pub fn protocol_fallback(&self) -> Option<(u32, u32)> {
        self.fallback
    }

    fn stream(&self, name: &'static str) -> Result<Vec<u8>> {
        let (_, data) = self
            .mpq
            .read_mpq_file_sector(name, false, &self.bytes)
            .map_err(|e| Error::MissingStream(name, format!("{e:?}")))?;
        Ok(data)
    }

    /// Raw `replay.details` (the whole `m_playerList`, cache handles…).
    pub fn details_raw(&self) -> Result<Value> {
        self.protocol
            .decode_details(&self.stream("replay.details")?)
    }

    /// Typed view of `replay.details`.
    pub fn details(&self) -> Result<ReplayDetails> {
        let raw = self.details_raw()?;
        let title = raw
            .field("m_title")
            .and_then(Value::as_str_lossy)
            .ok_or_else(|| Error::Corrupted("details without m_title".into()))?;
        let int = |v: &Value, name: &str| -> i64 {
            v.field(name).and_then(Value::as_int).unwrap_or_default()
        };
        let mut players = Vec::new();
        if let Some(list) = raw.field("m_playerList").and_then(Value::as_array) {
            for p in list {
                let toon = p.field("m_toon");
                let toon_handle = toon
                    .map(|t| {
                        format!(
                            "{}-Hero-{}-{}",
                            int(t, "m_region"),
                            int(t, "m_realm"),
                            int(t, "m_id")
                        )
                    })
                    .unwrap_or_default();
                players.push(PlayerDetails {
                    name: p
                        .field("m_name")
                        .and_then(Value::as_str_lossy)
                        .unwrap_or_default(),
                    hero: p
                        .field("m_hero")
                        .and_then(Value::as_str_lossy)
                        .unwrap_or_default(),
                    team_id: int(p, "m_teamId"),
                    result: int(p, "m_result"),
                    working_set_slot_id: p.field("m_workingSetSlotId").and_then(Value::as_int),
                    toon_handle,
                });
            }
        }
        Ok(ReplayDetails {
            title,
            time_utc: raw
                .field("m_timeUTC")
                .and_then(Value::as_int)
                .unwrap_or_default(),
            time_local_offset: raw
                .field("m_timeLocalOffset")
                .and_then(Value::as_int)
                .unwrap_or_default(),
            players,
        })
    }

    /// `replay.initData` brut (lobby complet — bitpacked).
    pub fn initdata_raw(&self) -> Result<Value> {
        self.protocol
            .decode_initdata(&self.stream("replay.initData")?)
    }

    /// `replay.attributes.events` (game mode, difficulty, lobby compositions…).
    pub fn attributes(&self) -> Result<Attributes> {
        attributes::decode_attributes(&self.stream("replay.attributes.events")?)
    }

    /// `replay.tracker.events` — stats, units, end-of-game score.
    pub fn tracker_events(&self) -> Result<Vec<Value>> {
        self.protocol
            .decode_tracker_events(&self.stream("replay.tracker.events")?)
    }

    /// `replay.game.events` — player inputs (orders, selections, talents…).
    pub fn game_events(&self) -> Result<Vec<Value>> {
        self.protocol
            .decode_game_events(&self.stream("replay.game.events")?)
    }

    /// Visits each game event (owned) without materialising a `Vec` — for the consumers
    /// (storm-stats, server) that only keep a handful of the ~100,000 events.
    pub fn visit_game_events<F: FnMut(Value)>(&self, f: F) -> Result<()> {
        self.protocol
            .visit_game_events(&self.stream("replay.game.events")?, f)
    }

    /// `replay.message.events` — chat and pings.
    pub fn message_events(&self) -> Result<Vec<Value>> {
        self.protocol
            .decode_message_events(&self.stream("replay.message.events")?)
    }

    /// Size of the decompressed game events stream without decoding it (perf diagnostic).
    #[doc(hidden)]
    pub fn game_events_raw_len(&self) -> Result<usize> {
        Ok(self.stream("replay.game.events")?.len())
    }

    /// Raw `replay.server.battlelobby` (not decoded — used to extract the BattleTags,
    /// like hots-parser).
    pub fn battlelobby_raw(&self) -> Result<Vec<u8>> {
        self.stream("replay.server.battlelobby")
    }

    /// Raw `replay.tracker.events` (not decoded) — the bytes the game writes into its temporary
    /// folder during the game; input of [`StreamDecoder`] (simulator, tests).
    pub fn tracker_events_raw(&self) -> Result<Vec<u8>> {
        self.stream("replay.tracker.events")
    }

    /// Raw `replay.game.events` (not decoded) — see [`Replay::tracker_events_raw`].
    pub fn game_events_raw(&self) -> Result<Vec<u8>> {
        self.stream("replay.game.events")
    }
}
